function buildSeed(){return seedRows.map((r,i)=>({id:'seed-'+(i+1),title:r[0],author:r[1],type:r[2],category:r[3],college:r[4],branch:r[5],year:r[6],semester:r[7],price:r[8],free:r[8]===0,sellerId:r[9],negotiation:r[10],showContact:r[11],condition:r[12],description:r[13],availability:'Available',createdAt:Date.now()-(i*86400000/3),theme:coverThemes[i%coverThemes.length],comments:[],offers:[],demo:true}));}
function readStore(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch(e){return fallback}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){console.warn('Storage unavailable',e);return false}}
