const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));
function persist(){if(liveMode)return;writeStore(DB.listings,listings);writeStore(DB.wishlist,wishlist);writeStore(DB.requests,requests);writeStore(DB.threads,threads)}
function userById(id){return liveProfiles[id]||demoUsers[id]||{id,name:'Campus Student',initials:'CS',college:'Student Community',branch:'General',year:1,semester:1,emailVerified:false,phoneVerified:false,collegeVerified:false,showContact:false,color:'blue'}}
function userWishlist(){if(liveMode){return Array.isArray(wishlist[currentUser.id])?wishlist[currentUser.id]:[]}return wishlist[currentUser.id]||(wishlist[currentUser.id]=[])}
function initials(name){return (name||'CS').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function formatPrice(p){return Number(p)===0?'FREE':'₹'+Number(p).toLocaleString('en-IN')}
function relativeDate(t){const days=Math.max(0,Math.floor((Date.now()-t)/86400000));if(days===0)return'Today';if(days===1)return'Yesterday';if(days<7)return days+' days ago';return Math.floor(days/7)+' weeks ago'}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sellerName(id){return userById(id).name}
function updateHeader(){const u=currentUser;const menuName=$('#menu-user-name');if(menuName)menuName.textContent=u.name;const avatar=$('.avatar-button .avatar');if(avatar){avatar.textContent=u.initials;avatar.className='avatar avatar-button-avatar avatar-'+(u.color||'blue')}const count=threads.filter(t=>t.members.includes(u.id)).length;const menu=$('#profile-menu');if(liveMode&&menu){menu.innerHTML=`<div class="profile-menu-head"><strong id="menu-user-name">${esc(u.name)}</strong><small>${currentAuthUser?'LIVE STUDENT ACCOUNT':'BROWSE MODE · SIGN IN TO PARTICIPATE'}</small></div>${currentAuthUser?'<button data-view="dashboard">My dashboard</button><button data-view="wishlist">My wishlist</button><button data-view="messages">Messages</button><div class="menu-divider"></div><button data-auth-action="logout">Sign out</button>':'<button data-action="open-login">Log in / Create account</button>'}`;}else if(menu){const menuCount=$('.menu-count');if(menuCount)menuCount.textContent=count;}}
function getFilteredListings(){
 let list=[...listings].filter(x=>x.availability==='Available');
 if(activeQuery){const q=activeQuery.toLowerCase();list=list.filter(x=>[x.title,x.author,x.category,x.type,x.subject,x.college,x.branch,x.semester,sellerName(x.sellerId)].join(' ').toLowerCase().includes(q))}
 if(quickFilter==='free')list=list.filter(x=>x.free);if(quickFilter==='books')list=list.filter(x=>x.type==='Books');if(quickFilter==='notes')list=list.filter(x=>x.type!=='Books');if(activeCategory)list=list.filter(x=>x.category===activeCategory||x.type===activeCategory);
 const college=$('#college-filter')?.value||'', sem=$('#semester-filter')?.value||'', subject=$('#subject-filter')?.value||'';
 if(college==='__other__'){const custom=$('#other-university-filter')?.value.trim().toLocaleLowerCase()||'';list=list.filter(x=>custom?String(x.college||'').toLocaleLowerCase()===custom:!UNIVERSITIES.includes(x.college));}else if(college)list=list.filter(x=>x.college===college);
 if(sem)list=list.filter(x=>String(x.semester)===sem);
 if(subject==='__other__'){const custom=$('#other-subject-filter')?.value.trim().toLocaleLowerCase()||'';list=list.filter(x=>custom?String(x.subject||'').toLocaleLowerCase()===custom:!SUBJECTS.includes(x.subject));}else if(subject)list=list.filter(x=>String(x.subject||'')===subject);
 const sort=$('#sort-filter')?.value||'recent';if(sort==='low')list.sort((a,b)=>a.price-b.price);else if(sort==='high')list.sort((a,b)=>b.price-a.price);else list.sort((a,b)=>b.createdAt-a.createdAt);return list
}
function populateBrowseFilters(){
 const college=$('#college-filter');if(!college)return;const previous=college.value;
 college.innerHTML='<option value="">All universities</option>'+UNIVERSITIES.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'<option value="__other__">Other / not listed</option>';
 if([...college.options].some(o=>o.value===previous))college.value=previous;
 toggleFilterOtherFields();populateSubjectFilter();
}
function populateSubjectFilter(){
 const select=$('#subject-filter');if(!select)return;const previous=select.value;
 const uni=$('#college-filter')?.value||'',sem=$('#semester-filter')?.value||'';
 let actual=listings.filter(x=>x.subject&&(!uni||uni==='__other__'||x.college===uni)&&(!sem||String(x.semester)===sem)).map(x=>String(x.subject).trim()).filter(Boolean);
 const values=[...new Set([...SUBJECTS,...actual])].filter(x=>x.toLowerCase()!=='other').sort((a,b)=>a.localeCompare(b));
 select.innerHTML='<option value="">All subjects</option>'+values.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'<option value="__other__">Other</option>';
 if([...select.options].some(o=>o.value===previous))select.value=previous;
 toggleFilterOtherFields();
}
function toggleFilterOtherFields(){
 const c=$('#college-filter'),s=$('#subject-filter'),ci=$('#other-university-filter'),si=$('#other-subject-filter');
 if(ci){ci.classList.toggle('hidden',c?.value!=='__other__');if(c?.value!=='__other__')ci.value='';}
 if(si){si.classList.toggle('hidden',s?.value!=='__other__');if(s?.value!=='__other__')si.value='';}
}
function syncOtherFormField(selectId,inputId){const select=document.getElementById(selectId),input=document.getElementById(inputId);if(!select||!input)return;const required=select.value==='__other__';input.closest('.form-field')?.classList.toggle('hidden',!required);input.required=required;if(!required)input.value='';}
function applySelectOrOther(form,field,value,otherField){const select=form.elements[field],input=form.elements[otherField];if(!select)return;const exists=[...select.options].some(o=>o.value===value);select.value=exists?value:'__other__';if(input){input.value=exists?'':(value||'');syncOtherFormField(field==='college'?'listing-college':'listing-subject',field==='college'?'other-college-input':'other-subject-input');}}

function coverMarkup(item,large=false){const theme=item.theme||coverThemes[0];const kind=item.type==='Books'?'book':(item.type==='PYQs'||item.type==='Lab Manuals'?'file':'notes');let inner='';if(kind==='book')inner=`<div class="cover-book" style="--cover:${theme.cover};--cover-text:${theme.text}"><small>${esc(item.category||'TEXTBOOK').toUpperCase()}</small><strong>${esc(item.title.split(/\s+/).slice(0,3).join('<br>'))}</strong><em>${esc(item.author||'STUDENT EDITION')}</em></div>`;else if(kind==='file')inner=`<div class="cover-file"><b style="font-size:10px">${item.type==='PYQs'?'PYQ':'LAB'}</b><span></span><span></span><span></span></div>`;else inner=`<div class="cover-notes"><b>${esc(item.title.split(/\s+/).slice(0,2).join(' '))}</b><span></span><span></span><span></span><span></span></div>`;return `<div class="product-visual ${large?'large':''}" style="--cover-bg:${theme.bg}">${inner}<span class="cover-sticker">${kind==='book'?'✧':kind==='file'?'PDF':'✎'}</span></div>`}
function cardMarkup(item){const seller=userById(item.sellerId),saved=userWishlist().includes(item.id);return `<article class="product-card" data-details="${esc(item.id)}">${coverMarkup(item)}<span class="product-badge ${item.free?'badge-free':item.type==='Books'?'badge-used':'badge-new'}">${item.free?'FREE RESOURCE':item.type==='Books'?'PRE-LOVED':'STUDENT RESOURCE'}</span><button class="wishlist-button ${saved?'saved':''}" data-wishlist="${esc(item.id)}" aria-label="${saved?'Remove from':'Add to'} wishlist">${saved?'♥':'♡'}</button><div class="product-info"><div class="product-category">${esc(item.category||item.type)}</div><h3 class="product-title">${esc(item.title)}</h3><div class="product-author">${esc(item.author||item.college)}</div><div class="product-meta"><span class="meta-chip">${esc(item.branch)}</span><span class="meta-chip">Sem ${item.semester}</span><span class="meta-chip">${esc(item.college.split(' ')[0])}</span></div><div class="product-bottom"><strong class="product-price ${item.free?'free':''}">${formatPrice(item.price)}</strong><div class="seller-mini"><span class="avatar avatar-${seller.color||'blue'}">${seller.initials||initials(seller.name)}</span><span>${esc(seller.name.split(' ')[0])}${seller.collegeVerified?'<b class="verified-mini">✓</b>':''}</span></div></div><div class="product-foot"><span>${item.demo?'DEMO LISTING':(liveMode?'STUDENT LISTING':relativeDate(item.createdAt))}</span><span class="negotiation-tag">${item.negotiation?'↔ Open to offers':'● '+(item.showContact?'Contact available':'In-app contact')}</span></div></div></article>`}
function renderGrid(targetId='listing-grid',list=getFilteredListings(),limit=visibleCount){const target=document.getElementById(targetId);if(!target)return;const shown=list.slice(0,limit);target.innerHTML=shown.length?shown.map(cardMarkup).join(''):`<div class="empty-state"><div class="empty-illustration">⌕</div><b>No matching resources just yet</b><span>Try another keyword or clear a filter. You can also request this material from the community.</span><br><button class="button button-small button-outline" data-action="open-request" style="margin-top:14px">Request this material</button></div>`;if(targetId==='listing-grid'){$('#result-count').textContent=`Showing ${shown.length} of ${list.length} resources`;$('#filter-summary').textContent=activeQuery?`Results for “${activeQuery}”`:activeCategory?`Category: ${activeCategory}`:'Across student communities';$('#load-more').classList.toggle('hidden',shown.length>=list.length);}}
function updateActiveNav(view){$$('.nav-link,.bottom-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view||(view==='explore'&&b.dataset.view==='home')))}
function showView(view){if(liveMode&&!currentAuthUser&&['dashboard','wishlist','messages'].includes(view)){openLoginModal();return}activeView=view;$('#home-page').classList.toggle('active',view==='home');$('#other-page').classList.toggle('active',view!=='home');updateActiveNav(view);$('#profile-menu').classList.add('hidden');if(view==='home'){window.scrollTo({top:0,behavior:'smooth'});renderGrid();return}renderSubpage(view);window.scrollTo({top:0,behavior:'smooth'})}
function subpageShell(kicker,title,description,body){$('#subpage-kicker').textContent=kicker;$('#subpage-title').textContent=title;$('#subpage-description').textContent=description;$('#subpage-content').innerHTML=body}
function renderSubpage(view){if(view==='books'||view==='notes'||view==='explore'){let list=listings.filter(x=>x.availability!=='Removed');if(view==='books')list=list.filter(x=>x.type==='Books');if(view==='notes')list=list.filter(x=>x.type!=='Books');subpageShell('BROWSE THE COMMUNITY',view==='books'?'Books worth passing on':view==='notes'?'Notes, PYQs & more':'Explore all materials',view==='books'?'Find affordable textbooks shared by fellow students.':view==='notes'?'Discover notes, practice papers, lab manuals and study guides.':'Browse the growing library of student-shared academic resources.',`<div class="subpage-tools"><input id="sub-search" placeholder="Search titles, authors, subjects..." value="${esc(activeQuery)}"><select id="sub-college"><option value="">All colleges</option><option>Chandigarh University</option><option>UIET Panjab University</option><option>Chitkara University</option><option>Thapar Institute</option></select><select id="sub-sem"><option value="">All semesters</option>${[1,2,3,4,5,6,7,8].map(s=>`<option value="${s}">Semester ${s}</option>`).join('')}</select><select id="sub-price"><option value="all">All prices</option><option value="free">Free only</option></select></div><div class="subpage-content-wrap"><div class="listing-grid" id="sub-listing-grid"></div></div>`);activeQuery='';const l=view==='books'?listings.filter(x=>x.type==='Books'):view==='notes'?listings.filter(x=>x.type!=='Books'):listings;renderGrid('sub-listing-grid',l,100);$('#sub-search').addEventListener('input',()=>{const q=$('#sub-search').value.toLowerCase();let f=l.filter(x=>[x.title,x.author,x.category,x.college,x.branch].join(' ').toLowerCase().includes(q));if($('#sub-college').value)f=f.filter(x=>x.college===$('#sub-college').value);if($('#sub-sem').value)f=f.filter(x=>String(x.semester)===$('#sub-sem').value);if($('#sub-price').value==='free')f=f.filter(x=>x.free);renderGrid('sub-listing-grid',f,100)});['sub-college','sub-sem','sub-price'].forEach(id=>$('#'+id).addEventListener('change',()=>$('#sub-search').dispatchEvent(new Event('input'))));return}
 if(view==='wishlist'){const saved=userWishlist().map(id=>listings.find(x=>x.id===id)).filter(Boolean);subpageShell('YOUR SAVED FINDS','Your wishlist','Keep the resources you like in one handy place.',`<div class="subpage-content-wrap"><div class="listing-grid" id="sub-listing-grid"></div></div>`);renderGrid('sub-listing-grid',saved,100);return}
 if(view==='requests'){subpageShell('COMMUNITY WISHLIST','Material requests','Students are looking for these resources. Have one? Reach out and help them out.',`<div class="subpage-tools"><button class="button button-primary" data-action="open-request">＋ Post a request</button></div><div class="subpage-content-wrap" id="requests-list"></div>`);renderRequests();return}
 if(view==='messages'){subpageShell('YOUR CAMPUS INBOX','Messages & conversations','Talk about a listing, ask for details or make a private offer.',`<div class="message-layout"><div class="panel"><div class="panel-heading"><h3>Conversations</h3><span class="section-kicker">${threads.filter(t=>t.members.includes(currentUser.id)).length} ACTIVE</span></div><div class="conversation-list" id="conversation-list"></div></div><div class="panel chat-panel" id="chat-panel"></div></div>`);renderMessages();return}
 if(view==='dashboard'){renderDashboard();return}
 subpageShell('CAMPUS HELP BRIDGE','Your student space','Your community dashboard is ready.',`<div class="subpage-content-wrap"><button class="button button-primary" data-view="dashboard">Open dashboard</button></div>`)}
function renderRequests(){const el=$('#requests-list');if(!el)return;el.innerHTML=requests.slice().sort((a,b)=>b.createdAt-a.createdAt).map(r=>{const u=userById(r.userId);return `<div class="request-card"><div class="request-icon">⌕</div><div class="request-main"><strong>${esc(r.title)}</strong><p>${esc(r.details)}</p><small>${esc(r.college)} · ${esc(r.branch)} · Sem ${r.semester} · ${esc(r.budget||'Flexible budget')}</small><small style="display:block;margin-top:5px">Requested by ${esc(u.name)} · ${relativeDate(r.createdAt)}</small></div><button class="button button-small button-outline" data-message-user="${esc(r.userId)}">I can help ↗</button></div>`}).join('')||'<div class="empty-state">No requests yet. Be the first to ask!</div>'}
function renderDashboard(){const own=listings.filter(x=>x.sellerId===currentUser.id&&x.availability!=='Removed');const received=listings.flatMap(x=>(x.offers||[]).filter(o=>x.sellerId===currentUser.id).map(o=>({...o,listing:x})));const sent=threads.filter(t=>t.members.includes(currentUser.id)).length;const saved=userWishlist().length;const allComments=listings.reduce((n,x)=>n+(x.comments||[]).filter(c=>c.userId!==currentUser.id&&x.sellerId===currentUser.id).length,0);subpageShell('YOUR CAMPUS CONTROL CENTRE','My dashboard','Keep your resources, conversations and exchanges moving.',`<div class="subpage-content-wrap"><div class="dashboard-grid"><div><div class="profile-hero-card"><span class="avatar profile-large">${currentUser.initials}</span><h2>${esc(currentUser.name)}</h2><p>${esc(currentUser.course)} · ${esc(currentUser.branch)} · Year ${currentUser.year} · Semester ${currentUser.semester}</p><div class="verify-pills"><span class="verify-pill">${currentUser.emailVerified?'✓ Email verified':'○ Email pending'}</span><span class="verify-pill ${currentUser.collegeVerified?'':'pending'}">${currentUser.collegeVerified?'✓ College verified':'○ College pending'}</span></div></div><div class="dashboard-metrics"><div class="metric-card"><strong>${own.length}</strong><small>My active listings</small></div><div class="metric-card"><strong>${saved}</strong><small>Saved resources</small></div><div class="metric-card"><strong>${received.length}</strong><small>Offers received</small></div><div class="metric-card"><strong>${sent}</strong><small>Conversations</small></div></div><div class="panel" style="margin-top:13px"><div class="panel-heading"><h3>Quick actions</h3></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="button button-small button-primary" data-action="open-sell">＋ List material</button><button class="button button-small button-outline" data-action="open-request">Request material</button><button class="button button-small button-muted" data-action="open-profile-settings">Privacy settings</button></div></div></div><div class="dashboard-main"><div class="panel"><div class="panel-heading"><h3>My listings</h3><button data-action="open-sell">＋ Add new</button></div><div class="dashboard-list">${own.length?own.slice(0,5).map(x=>`<div class="dashboard-row"><div class="dashboard-row-art">${x.type==='Books'?'▤':'✎'}</div><div class="dashboard-row-main"><strong>${esc(x.title)}</strong><small>${formatPrice(x.price)} · ${esc(x.college)} · Sem ${x.semester}</small></div><div class="seller-row-actions"><span class="status-label ${x.availability==='Sold'?'status-pending':''}">${esc(x.availability)}</span>${x.availability==='Available'?`<button data-edit-listing="${esc(x.id)}">Edit</button>`:''}<button data-listing-status="${esc(x.id)}" data-status="${x.availability==='Sold'?'Available':'Sold'}">${x.availability==='Sold'?'Re-list':'Mark sold'}</button><button data-remove-listing="${esc(x.id)}">Remove</button></div></div>`).join(''):'<div class="empty-state" style="padding:22px"><b>No listings yet</b><span>Share something useful with your campus.</span></div>'}</div></div><div class="panel"><div class="panel-heading"><h3>Offers I made</h3><span class="section-kicker">MY NEGOTIATIONS</span></div>${listings.flatMap(x=>(x.offers||[]).filter(o=>o.userId===currentUser.id&&x.sellerId!==currentUser.id).map(o=>({offer:o,listing:x}))).length?listings.flatMap(x=>(x.offers||[]).filter(o=>o.userId===currentUser.id&&x.sellerId!==currentUser.id).map(o=>({offer:o,listing:x}))).map(x=>`<div class="offer-row"><div><strong>${esc(x.listing.title)}</strong><small>Your offer · ${esc(x.offer.status)}</small></div><span class="offer-price">${formatPrice(x.offer.price)}</span></div>`).join(''):'<p class="trust-note">Offers you send on negotiable listings will appear here.</p>'}</div><div class="panel"><div class="panel-heading"><h3>Incoming offers</h3><span class="section-kicker">PRIVATE BARGAINING</span></div>${received.length?received.map(o=>`<div class="offer-row"><div><strong>${esc(o.listing.title)}</strong><small>Offer from ${esc(userById(o.userId).name)} · ${esc(o.message||'No message')}</small></div><span class="offer-price">${formatPrice(o.price)}</span><div class="offer-actions"><button data-offer="${esc(o.id)}" data-offer-action="accept">Accept</button><button class="reject" data-offer="${esc(o.id)}" data-offer-action="reject">Decline</button></div></div>`).join(''):'<p class="trust-note">No offers yet. When a buyer makes a private offer on a negotiable listing, it will appear here.</p>'}</div><div class="panel"><div class="panel-heading"><h3>Contact information</h3></div><form id="phone-contact-form" class="phone-contact-form"><div class="form-field"><label for="phone-number-input">Mobile number</label><div class="phone-input-wrap"><span>+91</span><input id="phone-number-input" name="phone_number" type="tel" inputmode="numeric" autocomplete="tel-national" maxlength="10" pattern="[6-9][0-9]{9}" placeholder="10-digit mobile number" required></div></div><p class="trust-note phone-private-note">Your number is saved privately and is not shown to other students.</p><div class="form-actions"><button class="button button-primary" type="submit">Save phone number</button><button class="button button-outline" type="button" data-action="remove-phone-number">Remove number</button></div></form></div><div class="panel"><div class="panel-heading"><h3>Account & privacy</h3><button data-action="open-profile-settings">Manage</button></div><div class="dashboard-list"><div class="dashboard-row"><div class="dashboard-row-art">↔</div><div class="dashboard-row-main"><strong>Negotiation preferences</strong><small>Each listing controls its own bargaining setting.</small></div></div></div></div></div></div></div>`);loadPhoneNumberIntoDashboard()}
function loadPhoneNumberIntoDashboard(){const input=$('#phone-number-input');if(!input)return;if(!liveMode||!currentAuthUser){input.disabled=true;return}CHB.getMyPhone(currentAuthUser.id).then(phone=>{const current=$('#phone-number-input');if(current)current.value=phone?phone.replace(/^\+91/,''):'';const note=$('#phone-contact-form .phone-private-note');if(note&&phone)note.textContent='✓ Your mobile number is OTP-verified and stored privately. You can remove it or update it with a new OTP.'}).catch(err=>toast('Could not load your saved phone number: '+err.message))}
function renderMessages(){const mine=threads.filter(t=>t.members.includes(currentUser.id));const list=$('#conversation-list');if(!list)return;list.innerHTML=mine.map(t=>{const other=t.members.find(x=>x!==currentUser.id);const u=userById(other);const last=t.messages[t.messages.length-1];return `<button class="conversation ${t.id===selectedThreadId?'active':''}" data-thread="${t.id}"><span class="avatar avatar-${u.color||'blue'}">${u.initials}</span><span><strong>${esc(u.name)}</strong><small>${esc(last?.text||'Start a conversation')}</small></span></button>`}).join('')||'<div class="trust-note">No conversations yet. Open a listing and contact a seller to start one.</div>';if(!selectedThreadId||!mine.some(t=>t.id===selectedThreadId))selectedThreadId=mine[0]?.id||null;renderChatPanel()}
function renderChatPanel(){const el=$('#chat-panel');if(!el)return;const t=threads.find(x=>x.id===selectedThreadId&&x.members.includes(currentUser.id));if(!t){el.innerHTML='<div class="empty-state" style="margin:auto"><div class="empty-illustration">✉</div><b>Your conversations live here</b><span>Choose a conversation or contact a seller from a listing.</span></div>';return}const other=t.members.find(x=>x!==currentUser.id),u=userById(other),listing=listings.find(x=>x.id===t.listingId);el.innerHTML=`<div class="panel-heading"><div><h3>${esc(u.name)}</h3><small style="font-size:8px;color:#999">${listing?'About: '+esc(listing.title):'Campus Help chat'}</small></div><span class="verify-pill" style="background:#e6f8f0;color:#329a7b">Private chat</span></div><div class="chat-messages" id="chat-messages">${t.messages.map(m=>`<div class="chat-bubble ${m.from===currentUser.id?'mine':'theirs'}">${esc(m.text)}</div>`).join('')}</div><form class="chat-compose" id="chat-form"><input name="message" placeholder="Write a message..." autocomplete="off" required><button type="submit">Send ↗</button></form>`;const box=$('#chat-messages');box.scrollTop=box.scrollHeight}
function createThread(userId,listingId){let t=threads.find(x=>x.members.includes(currentUser.id)&&x.members.includes(userId)&&x.listingId===listingId);if(!t){t={id:'thread-'+Date.now(),members:[currentUser.id,userId],listingId,messages:[]};threads.unshift(t);persist()}selectedThreadId=t.id;return t}
async function openMessage(userId,listingId,initialText=''){if(liveMode){if(!currentAuthUser){openLoginModal();return}if(userId===currentUser.id){toast('That is your own listing.');return}try{const conv=await CHB.startConversation(currentUser.id,userId,listingId||null);if(initialText){await CHB.client.from('messages').insert({conversation_id:conv.id,sender_id:currentUser.id,body:initialText}).then(({error})=>{if(error)throw error;});}threads=await CHB.loadThreads(currentUser.id);threads.forEach(x=>Object.assign(liveProfiles,x.profiles||{}));selectedThreadId=conv.id;closeModal();showView('messages');renderMessages();return;}catch(err){toast(err.message);return}}if(userId===currentUser.id){toast('That is your own listing.');return}const t=createThread(userId,listingId);if(initialText&&!t.messages.some(m=>m.from===currentUser.id&&m.text===initialText)){t.messages.push({from:currentUser.id,text:initialText,time:Date.now()});persist()}closeModal();showView('messages');renderMessages();}
function toast(message){const n=document.createElement('div');n.className='toast';n.innerHTML=`<i>✓</i><span>${esc(message)}</span>`;$('#toast-region').appendChild(n);setTimeout(()=>n.remove(),3200)}
function showModal(html,small=false){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-close-backdrop><div class="modal ${small?'modal-small':''}" role="dialog" aria-modal="true">${html}</div></div>`;document.body.style.overflow='hidden'}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow=''}
function openListing(id){const item=listings.find(x=>x.id===id);if(!item)return;if(liveMode&&!item.commentsLoaded){item.commentsLoaded=true;CHB.loadComments(id).then(rows=>{item.comments=rows;rows.forEach(r=>{if(r.profile)liveProfiles[r.userId]=r.profile});openListing(id)}).catch(err=>{item.comments=[];toast('Could not load questions: '+err.message);openListing(id)});return}modalListingId=id;const s=userById(item.sellerId);const comments=item.comments||[];const sellerContact=item.showContact&&s.showContact;showModal(`<div class="modal-header"><div><div class="section-kicker">${esc(item.category||item.type).toUpperCase()} · ${esc(item.college)}</div><h2>Resource details</h2></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="detail-layout"><div class="detail-visual" style="--cover-bg:${item.theme?.bg||'#f3edff'}">${coverMarkup(item)}</div><div class="detail-main"><div class="product-category">${esc(item.category||item.type)}</div><h2>${esc(item.title)}</h2><div class="detail-author">${esc(item.author||'Student-shared resource')} · ${esc(item.condition||'Digital')}</div><div class="detail-price ${item.free?'free':''}">${formatPrice(item.price)}</div><div class="detail-tags"><span class="meta-chip">${esc(item.branch)}</span><span class="meta-chip">Year ${item.year}</span><span class="meta-chip">Semester ${item.semester}</span><span class="meta-chip">${esc(item.college)}</span></div><p class="detail-description">${esc(item.description)}</p><div class="seller-card"><span class="avatar avatar-${s.color||'blue'}">${s.initials}</span><div><strong>${esc(s.name)} ${s.collegeVerified?'<span class="verified-mini">✓ College verified</span>':''}</strong><small>${esc(s.course||'Student')} · ${esc(s.branch||'')} · Year ${s.year||'—'} · ${liveMode?'LIVE STUDENT':'DEMO PROFILE'}</small></div><span class="seller-verified">${s.collegeVerified?'✓ VERIFIED':'STUDENT'}</span></div>${liveMode?'<div class="contact-note contact-private">🔒 Personal phone numbers are not displayed. Contact the student through private Campus Help messages.</div>':(sellerContact?'<div class="contact-note">✓ Seller has opted to display contact details. Demo contact: <b>+91 90000 00000</b> <span style="opacity:.8">(fictional demo number — not a real contact)</span>.</div>':'<div class="contact-note contact-private">🔒 Seller keeps their personal contact private. You can still ask questions or message them safely here.</div>')}<div class="detail-actions"><button class="button button-primary button-small" data-request-buy="${esc(item.id)}">${item.free?'Request free resource':'Request to buy'} ↗</button><button class="button button-outline button-small" data-contact="${esc(item.sellerId)}" data-listing="${esc(item.id)}">Message seller</button>${item.negotiation?'<button class="button button-outline button-small" data-make-offer="'+esc(item.id)+'">Make an offer</button>':''}${liveMode&&item.filePath?'<button class="button button-outline button-small" data-download="'+esc(item.id)+'">Download material ↓</button>':''}<button class="button button-muted button-small" data-wishlist="${esc(item.id)}">${userWishlist().includes(item.id)?'♥ Saved':'♡ Save'}</button></div></div></div><div class="trust-note">Seller contact is controlled by the seller. Public questions are visible on this listing; private messages and offers are only visible to the participants.</div><div class="comment-section"><h3>Questions & discussion <span style="color:#aaa;font-weight:500">(${comments.length})</span></h3><form class="comment-compose" id="comment-form"><input name="comment" placeholder="Ask about availability, condition, topics included..." maxlength="300" required><button type="submit">Post</button></form><div class="comment-list">${comments.length?comments.map(c=>`<div class="comment-item"><span class="avatar avatar-${userById(c.userId).color||'blue'}">${initials(userById(c.userId).name)}</span><div class="comment-body"><strong>${esc(userById(c.userId).name)}</strong><small>${relativeDate(c.createdAt)}</small><p>${esc(c.text)}</p></div></div>`).join(''):'<div class="trust-note">No questions yet. Be the first to ask something helpful.</div>'}</div></div></div>`);}
function openSellModal(editId=null){
 const editItem=editId?listings.find(x=>x.id===editId):null;let kind=editItem&&editItem.type==='Books'?'Books':'Notes';
 const universityOptions=UNIVERSITIES.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
 const subjectOptions=SUBJECTS.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
 showModal(`<div class="modal-header"><div><div class="section-kicker">PASS IT FORWARD</div><h2>Share a resource</h2><p>List a useful find for someone in your student community.</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="listing-type-toggle"><button class="${kind==='Books'?'selected':''}" data-listing-kind="Books"><strong>▤ Books & physical</strong><small>Textbooks, equipment, stationery</small></button><button class="${kind==='Notes'?'selected':''}" data-listing-kind="Notes"><strong>✎ Notes & digital</strong><small>Notes, PYQs, PDFs, lab files</small></button></div><form id="listing-form"><input type="hidden" name="kind" value="${kind}"><div class="form-grid"><div class="form-field full"><label>Title *</label><input name="title" required placeholder="e.g. Engineering Mathematics-I"></div><div class="form-field"><label>Author / Created by</label><input name="author" placeholder="e.g. B.S. Grewal"></div><div class="form-field"><label>Subject *</label><select name="subject" id="listing-subject" required><option value="">Select subject</option>${subjectOptions}<option value="__other__">Other</option></select></div><div class="form-field full hidden"><label>Enter subject name *</label><input name="other_subject" id="other-subject-input" maxlength="120" placeholder="Type the subject name"></div><div class="form-field"><label>University *</label><select name="college" id="listing-college" required><option value="">Select university</option>${universityOptions}<option value="__other__">Other / not listed</option></select></div><div class="form-field hidden"><label>Enter university name *</label><input name="other_college" id="other-college-input" maxlength="140" placeholder="Type your university name"></div><div class="form-field"><label>Course / Branch *</label><select name="branch"><option>CSE</option><option>ECE</option><option>Mechanical</option><option>Electrical</option><option>Biotechnology</option><option>Other</option></select></div><div class="form-field"><label>Academic year</label><select name="year"><option value="1">1st Year</option><option value="2">2nd Year</option><option value="3">3rd Year</option><option value="4">4th Year</option></select></div><div class="form-field"><label>Semester *</label><select name="semester">${[1,2,3,4,5,6,7,8].map(s=>`<option value="${s}" ${currentUser.semester===s?'selected':''}>Semester ${s}</option>`).join('')}</select></div><div class="form-field"><label>Material category</label><select name="category" id="listing-category"><option>Textbooks</option><option>Handwritten Notes</option><option>Digital Notes</option><option>PYQs</option><option>Lab Manuals</option><option>Study Guides</option><option>Other Academic Resources</option></select></div><div class="form-field"><label>Price (₹) — enter 0 for FREE</label><input name="price" type="number" min="0" value="0" required></div><div class="form-field"><label>${kind==='Books'?'Book condition':'File format / condition'}</label><select name="condition"><option>Good</option><option>Like New</option><option>New</option><option>Acceptable</option><option>Digital</option></select></div><div class="form-field full"><label>Description *</label><textarea name="description" required placeholder="What is included? Mention edition, topics, condition or any helpful details..."></textarea></div><div class="form-field full"><label>Cover image / material preview (optional)</label><div class="upload-drop">＋ Add a cover image or preview<input type="file" name="cover" accept="image/*,.pdf"></div><span class="form-help">${liveMode?'Real upload: PDF, JPG, PNG or WEBP, maximum 10 MB. Files are stored in private student-resource storage.':'Demo prototype: file names are recorded locally; secure hosted file storage is not connected.'}</span></div><div class="form-field full"><div class="negotiation-box"><strong>Allow price negotiation?</strong><div class="segmented"><button type="button" class="selected" data-toggle-choice="negotiation" data-value="yes">Yes, open to offers</button><button type="button" data-toggle-choice="negotiation" data-value="no">No, fixed price</button></div><input type="hidden" name="negotiation" value="yes"></div></div><div class="form-field full"><div class="negotiation-box"><strong>Would you like to display your contact number?</strong><div class="segmented"><button type="button" data-toggle-choice="contact" data-value="yes">Yes, show my contact</button><button type="button" class="selected" data-toggle-choice="contact" data-value="no">No, keep it private</button></div><input type="hidden" name="showContact" value="no"><span class="form-help">Default is private. Public contact display stays disabled until real phone OTP verification is available. In-app messages remain available.</span></div></div></div><div class="form-actions"><button type="button" class="button button-muted" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">Publish listing ↗</button></div></form></div>`);
 const f=$('#listing-form');
 if(editItem){f.dataset.editId=editItem.id;['title','author','branch','year','semester','category','price','condition','description'].forEach(k=>{if(f.elements[k])f.elements[k].value=editItem[k]??''});applySelectOrOther(f,'subject',editItem.subject||'','other_subject');applySelectOrOther(f,'college',editItem.college||'','other_college');f.elements.negotiation.value=editItem.negotiation?'yes':'no';f.elements.showContact.value=editItem.showContact?'yes':'no';f.querySelectorAll('[data-toggle-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.value===(b.dataset.toggleChoice==='negotiation'?f.elements.negotiation.value:f.elements.showContact.value)));$('.modal-header h2').textContent='Edit your listing';f.querySelector('button[type="submit"]').textContent='Save changes ↗';}
 f.querySelector('#listing-subject').addEventListener('change',()=>syncOtherFormField('listing-subject','other-subject-input'));
 f.querySelector('#listing-college').addEventListener('change',()=>syncOtherFormField('listing-college','other-college-input'));
}

function openRequestModal(){showModal(`<div class="modal-header"><div><div class="section-kicker">ASK YOUR COMMUNITY</div><h2>Request a material</h2><p>Someone on campus might already have what you need.</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><form id="request-form"><div class="form-grid"><div class="form-field full"><label>What are you looking for? *</label><input name="title" required placeholder="e.g. Engineering Mathematics-I textbook"></div><div class="form-field"><label>Subject</label><input name="subject" placeholder="Mathematics"></div><div class="form-field"><label>College</label><select name="college"><option>Chandigarh University</option><option>UIET Panjab University</option><option>Chitkara University</option><option>Thapar Institute</option></select></div><div class="form-field"><label>Branch</label><input name="branch" value="${esc(currentUser.branch)}"></div><div class="form-field"><label>Semester</label><select name="semester">${[1,2,3,4,5,6,7,8].map(s=>`<option value="${s}" ${s===currentUser.semester?'selected':''}>Semester ${s}</option>`).join('')}</select></div><div class="form-field full"><label>Preferred budget</label><select name="budget"><option>Free preferred</option><option>Under ₹100</option><option>Under ₹200</option><option>₹200–₹500</option><option>Flexible budget</option></select></div><div class="form-field full"><label>Any extra details?</label><textarea name="details" placeholder="Edition, format, topic or when you need it..."></textarea></div></div><div class="form-actions"><button type="button" class="button button-muted" data-action="close-modal">Cancel</button><button class="button button-primary">Post request ↗</button></div></form></div>`)}
function openLoginModal(mode='login'){
  authMode=mode;
  if(!liveMode){showModal(`<div class="modal-header"><div><div class="section-kicker">WELCOME TO YOUR CAMPUS COMMUNITY</div><h2>Choose a demo profile</h2><p>Explore buyer and seller journeys without using real student data.</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="login-demo-list">${Object.values(demoUsers).map(u=>`<button class="demo-user-choice" data-login-user="${u.id}"><span class="avatar avatar-${u.color}">${u.initials}</span><span><strong>${esc(u.name)}</strong><small>${esc(u.college)} · ${esc(u.branch)} · Sem ${u.semester}</small></span><span class="demo-label">DEMO</span></button>`).join('')}</div><div class="modal-notice">Demo profiles are fictional and local to this browser.</div></div>`);return;}
  const isSignup=authMode==='signup';
  showModal(`<div class="modal-header"><div><div class="section-kicker">YOUR CAMPUS COMMUNITY</div><h2>${isSignup?'Create your student account':'Welcome back'}</h2><p>${isSignup?'Use your own email and academic details.':'Sign in to publish and contact real student listings.'}</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="auth-mode-tabs"><button type="button" data-auth-mode="login" class="${!isSignup?'selected':''}">Log in</button><button type="button" data-auth-mode="signup" class="${isSignup?'selected':''}">Create account</button></div><form id="auth-form" data-mode="${authMode}">${isSignup?`<div class="form-grid"><div class="form-field full"><label>Full name *</label><input name="full_name" required maxlength="80" placeholder="Your name"></div><div class="form-field full"><label>College / University *</label><input name="college" required maxlength="120" placeholder="e.g. Chandigarh University"></div><div class="form-field"><label>Course *</label><input name="course" required value="B.Tech" placeholder="B.Tech"></div><div class="form-field"><label>Branch *</label><input name="branch" required placeholder="CSE, ECE, etc."></div><div class="form-field"><label>Academic year *</label><select name="academic_year"><option value="1">1st Year</option><option value="2">2nd Year</option><option value="3">3rd Year</option><option value="4">4th Year</option></select></div><div class="form-field"><label>Current semester *</label><select name="semester">${[1,2,3,4,5,6,7,8].map(x=>`<option value="${x}">Semester ${x}</option>`).join('')}</select></div></div>`:''}<div class="form-field"><label>Email address *</label><input type="email" name="email" autocomplete="email" required placeholder="you@example.com"></div><div class="form-field"><label>Password *</label><input type="password" name="password" autocomplete="${isSignup?'new-password':'current-password'}" minlength="8" required placeholder="At least 8 characters"></div><button class="button button-primary auth-submit" type="submit">${isSignup?'Create account':'Log in'} ↗</button></form><div class="auth-divider"><span>OR</span></div><button class="button button-outline auth-google" type="button" data-auth-action="google">Continue with Google</button><p class="auth-footnote">Supabase Free's built-in email sender is restricted to project team addresses and 2 emails/hour. For real student sign-ups, enable Google OAuth or configure a custom SMTP sender. College verification is a separate review and is never assumed from Google login.</p></div>`);
}
function openProfileCompletionModal(){showModal(`<div class="modal-header"><div><div class="section-kicker">ONE LAST STEP</div><h2>Complete your student profile</h2><p>Add your academic details before joining the marketplace.</p></div></div><div class="modal-body"><form id="profile-completion-form"><div class="form-grid"><div class="form-field full"><label>Full name *</label><input name="full_name" required value="${esc(currentUser.name==='Campus Student'?'':currentUser.name)}"></div><div class="form-field full"><label>College / University *</label><input name="college" required placeholder="Your college"></div><div class="form-field"><label>Course *</label><input name="course" required value="B.Tech"></div><div class="form-field"><label>Branch *</label><input name="branch" required placeholder="CSE, ECE, etc."></div><div class="form-field"><label>Academic year</label><select name="academic_year">${[1,2,3,4].map(x=>`<option value="${x}">Year ${x}</option>`).join('')}</select></div><div class="form-field"><label>Semester</label><select name="semester">${[1,2,3,4,5,6,7,8].map(x=>`<option value="${x}">Semester ${x}</option>`).join('')}</select></div></div><button class="button button-primary auth-submit" type="submit">Save student profile ↗</button></form><p class="auth-footnote">You can add a phone number later from My Dashboard. It is kept private and is not displayed to other students.</p></div>`);}
async function submitAuthForm(form){const fd=new FormData(form), mode=form.dataset.mode;const email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||'');try{if(mode==='signup'){const meta={full_name:String(fd.get('full_name')).trim(),college:String(fd.get('college')).trim(),course:String(fd.get('course')).trim(),branch:String(fd.get('branch')).trim(),academic_year:Number(fd.get('academic_year')),semester:Number(fd.get('semester'))};const {data,error}=await CHB.client.auth.signUp({email,password,options:{data:meta,emailRedirectTo:location.origin}});if(error)throw error;if(data.user&&data.session){currentAuthUser=data.user;const profile=await CHB.saveProfile(data.user,meta);liveProfiles[profile.id]=profile;currentUser=profile;closeModal();await refreshLiveData();updateHeader();toast('Your account is ready. Welcome to Campus Help Bridge!');}else{closeModal();toast('Account created. Check your email to confirm your address, then log in.');}}else{const {data,error}=await CHB.client.auth.signInWithPassword({email,password});if(error)throw error;currentAuthUser=data.user;await activateLiveUser(data.user);closeModal();toast('You are now signed in.');}}catch(err){const msg=String(err.message||'');toast(/email address not authorized|rate limit|email rate limit/i.test(msg)?'Supabase default email delivery is limited on the Free plan. Enable Google sign-in or configure a custom email sender.':(msg||'Authentication failed. Please try again.'));}}
async function activateLiveUser(user){currentAuthUser=user;let profile=await CHB.getProfile(user.id);if(!profile){profile=await CHB.saveProfile(user,{full_name:user.user_metadata?.full_name||user.email?.split('@')[0],college:user.user_metadata?.college||'',course:user.user_metadata?.course||'',branch:user.user_metadata?.branch||'',academic_year:user.user_metadata?.academic_year||1,semester:user.user_metadata?.semester||1});}liveProfiles[user.id]=profile;currentUser=profile;await refreshLiveData();updateHeader();if(!profile.college||!profile.branch)openProfileCompletionModal();}
async function refreshLiveData(){if(!liveMode)return;const loaded=await CHB.loadListings(currentAuthUser?.id);listings=loaded.listings;liveProfiles={...liveProfiles,...loaded.profiles};if(currentAuthUser){const p=await CHB.getProfile(currentAuthUser.id);if(p){currentUser=p;liveProfiles[p.id]=p;}wishlist={[currentUser.id]:await CHB.loadWishlist(currentUser.id)};await CHB.loadOffers(currentUser.id,listings);threads=await CHB.loadThreads(currentUser.id);threads.forEach(t=>Object.assign(liveProfiles,t.profiles||{}));}else{wishlist={};threads=[];}requests=await CHB.loadRequests();requests.forEach(r=>{if(r.profile)liveProfiles[r.userId]=r.profile});populateSubjectFilter();renderGrid();if(activeView==='dashboard')renderDashboard();if(activeView==='messages')renderMessages();if(activeView==='requests')renderRequests();updateHeader();}
async function initializeLiveMode(){if(!window.CHB?.configured)return;liveMode=true;listings=[];requests=[];threads=[];wishlist={};currentUser={id:'guest',name:'Campus Guest',initials:'CG',college:'Browse mode',course:'',branch:'',year:1,semester:1,emailVerified:false,phoneVerified:false,collegeVerified:false,showContact:false,color:'blue'};$('#mode-badge').textContent='LIVE COMMUNITY';$('.stats-strip').innerHTML='<div><span class="stat-icon stat-violet">▤</span><span><strong>Real listings</strong><small>Shared by signed-in students</small></span></div><div><span class="stat-icon stat-coral">♡</span><span><strong>Free & fair</strong><small>Student-first pricing</small></span></div><div><span class="stat-icon stat-mint">✓</span><span><strong>Verification-aware</strong><small>College status shown separately</small></span></div><div><span class="stat-icon stat-yellow">↗</span><span><strong>Shared campus</strong><small>One student community</small></span></div>';document.querySelector('.footer-copy').textContent='© 2026 Campus Help Bridge · Live student community';updateHeader();try{const {data,error}=await CHB.client.auth.getSession();if(error)throw error;if(data.session)await activateLiveUser(data.session.user);else await refreshLiveData();CHB.client.auth.onAuthStateChange((event,session)=>{Promise.resolve().then(async()=>{if(event==='SIGNED_OUT'){currentAuthUser=null;liveProfiles={};currentUser={id:'guest',name:'Campus Guest',initials:'CG',college:'Browse mode',course:'',branch:'',year:1,semester:1,emailVerified:false,phoneVerified:false,collegeVerified:false,showContact:false,color:'blue'};await refreshLiveData();}else if(session&&(event==='SIGNED_IN'||event==='TOKEN_REFRESHED'||event==='USER_UPDATED')){try{await activateLiveUser(session.user);}catch(e){toast(e.message);}}});});}catch(err){toast('Backend connection failed: '+err.message);}}
function openProfileSettings(){showModal(`<div class="modal-header"><div><div class="section-kicker">YOUR PROFILE, YOUR CHOICE</div><h2>Privacy settings</h2><p>Control what other students can see.</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><p class="trust-note">Your phone number is stored separately from your public student profile and is not shown to other students. You can add or remove it from the Contact Information section in My Dashboard. Students can contact each other through private in-app messages.</p><div class="form-actions"><button class="button button-primary" data-action="close-modal" type="button">Done</button></div></div>`)}
async function submitPhoneContact(){toast('Use Send OTP to verify your number before it is saved.');}

function handleClick(e){const authModeBtn=e.target.closest('[data-auth-mode]');if(authModeBtn){openLoginModal(authModeBtn.dataset.authMode);return}const authAction=e.target.closest('[data-auth-action]')?.dataset.authAction;if(authAction==='google'){CHB.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin}}).then(({error})=>{if(error)toast(error.message)});return}if(authAction==='logout'){CHB.client.auth.signOut().then(({error})=>{if(error)toast(error.message);else toast('Signed out.')});return}const download=e.target.closest('[data-download]');if(download){const item=listings.find(x=>x.id===download.dataset.download);if(item?.filePath){if(!currentAuthUser){openLoginModal();return}CHB.getFileUrl(item.filePath).then(url=>{const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click()}).catch(err=>toast(err.message));}return}const view=e.target.closest('[data-view]');if(view){e.preventDefault();showView(view.dataset.view);return}const wl=e.target.closest('[data-wishlist]');if(wl){e.stopPropagation();toggleWishlist(wl.dataset.wishlist);if(modalListingId)openListing(modalListingId);else if(activeView==='wishlist')renderSubpage('wishlist');else renderGrid();return}const details=e.target.closest('[data-details]');if(details){openListing(details.dataset.details);return}const cat=e.target.closest('[data-category]');if(cat){activeCategory=cat.dataset.category;activeQuery='';quickFilter='all';$('#search-input').value='';$$('.filter-tab').forEach(x=>x.classList.remove('active'));$('[data-quick-filter="all"]').classList.add('active');renderGrid();document.querySelector('#marketplace').scrollIntoView({behavior:'smooth'});return}const quick=e.target.closest('[data-quick-filter]');if(quick){quickFilter=quick.dataset.quickFilter;activeCategory='';$$('.filter-tab').forEach(x=>x.classList.toggle('active',x===quick));renderGrid();return}const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='open-sell'){if(liveMode&&!currentAuthUser){openLoginModal();return}openSellModal()}if(action==='open-request'){if(liveMode&&!currentAuthUser){openLoginModal();return}openRequestModal()}if(action==='close-modal')closeModal();if(action==='open-login')openLoginModal();if(action==='scroll-market')document.querySelector('#marketplace').scrollIntoView({behavior:'smooth'});if(action==='open-profile-settings')openProfileSettings();if(action==='remove-phone-number'){if(!liveMode||!currentAuthUser){toast('Please sign in first.');return}if(!confirm('Remove your saved phone number from your private account?'))return;CHB.deleteMyPhone(currentAuthUser.id).then(()=>{const input=$('#phone-number-input');if(input)input.value='';toast('Phone number removed.')}).catch(err=>toast('Could not remove phone number: '+err.message));return}return}const kind=e.target.closest('[data-listing-kind]');if(kind){$$('[data-listing-kind]').forEach(x=>x.classList.toggle('selected',x===kind));const f=$('#listing-form');f.elements.kind.value=kind.dataset.listingKind;$('#listing-category').value=kind.dataset.listingKind==='Books'?'Textbooks':'Handwritten Notes';return}const toggle=e.target.closest('[data-toggle-choice]');if(toggle){const group=toggle.dataset.toggleChoice;if(group==='contact'&&toggle.dataset.value==='yes'&&!currentUser.phoneVerified){toast(liveMode?'Personal phone display is not enabled in the live version yet. Use private in-app messages instead.':'Phone verification is required before contact details can be displayed.');return}const parent=toggle.parentElement;parent.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===toggle));const inp=parent.parentElement.querySelector(`input[name="${group}"]`)||parent.nextElementSibling;if(inp)inp.value=toggle.dataset.value;return}const login=e.target.closest('[data-login-user]');if(login&&!liveMode){currentUser=demoUsers[login.dataset.loginUser];writeStore(DB.users,currentUser.id);updateHeader();closeModal();toast(`Welcome, ${currentUser.name.split(' ')[0]}! Demo profile switched.`);if(activeView==='dashboard')renderDashboard();return}const contact=e.target.closest('[data-contact]');if(contact){openMessage(contact.dataset.contact,contact.dataset.listing);return}const buy=e.target.closest('[data-request-buy]');if(buy){const item=listings.find(x=>x.id===buy.dataset.requestBuy);if(item)openMessage(item.sellerId,item.id,`Hi! I am interested in ${item.free?'getting':'buying'} your listing: ${item.title}. Is it still available?`);return}const status=e.target.closest('[data-listing-status]');if(status){const item=listings.find(x=>x.id===status.dataset.listingStatus);if(item){if(liveMode){CHB.setListingStatus(item.id,status.dataset.status).then(()=>refreshLiveData()).then(()=>toast(status.dataset.status==='Available'?'Listing is available again.':'Listing marked as sold.')).catch(err=>toast(err.message));}else{item.availability=status.dataset.status;persist();renderDashboard();renderGrid();toast(item.availability==='Available'?'Listing is available again.':'Listing marked as sold.')}}return}const edit=e.target.closest('[data-edit-listing]');if(edit){openSellModal(edit.dataset.editListing);return}const remove=e.target.closest('[data-remove-listing]');if(remove){const item=listings.find(x=>x.id===remove.dataset.removeListing);if(item){if(liveMode){CHB.setListingStatus(item.id,'Removed').then(()=>refreshLiveData()).then(()=>toast('Listing removed from the marketplace.')).catch(err=>toast(err.message));}else{item.availability='Removed';persist();renderDashboard();renderGrid();toast('Listing removed from your marketplace.')}}return}const msgUser=e.target.closest('[data-message-user]');if(msgUser){openMessage(msgUser.dataset.messageUser,'');return}const offerBtn=e.target.closest('[data-make-offer]');if(offerBtn){openOfferModal(offerBtn.dataset.makeOffer);return}const thread=e.target.closest('[data-thread]');if(thread){selectedThreadId=thread.dataset.thread;renderMessages();return}const offerAction=e.target.closest('[data-offer-action]');if(offerAction){updateOffer(offerAction.dataset.offer,offerAction.dataset.offerAction);return}const offerRow=e.target.closest('[data-offer]');if(offerRow&&!offerAction){return}if(e.target.closest('[data-close-backdrop]')&&e.target.classList.contains('modal-backdrop'))closeModal();}
async function toggleWishlist(id){if(liveMode){if(!currentAuthUser){openLoginModal();return}const list=userWishlist();const shouldSave=!list.includes(id);try{await CHB.toggleWishlist(currentUser.id,id,shouldSave);wishlist[currentUser.id]=shouldSave?[...list,id]:list.filter(x=>x!==id);toast(shouldSave?'Saved to your wishlist.':'Removed from your wishlist.');if(modalListingId)openListing(modalListingId);else if(activeView==='wishlist')renderSubpage('wishlist');else renderGrid();}catch(err){toast(err.message)}return}const list=userWishlist();const idx=list.indexOf(id);if(idx>=0){list.splice(idx,1);toast('Removed from your wishlist.')}else{list.push(id);toast('Saved to your wishlist.')}persist()}
function openOfferModal(id){const item=listings.find(x=>x.id===id);if(!item||!item.negotiation){toast('This seller has chosen a fixed price.');return}showModal(`<div class="modal-header"><div><div class="section-kicker">PRIVATE NEGOTIATION</div><h2>Make an offer</h2><p>Your offer is visible only to the seller.</p></div><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="request-card"><div class="request-icon">↔</div><div class="request-main"><strong>${esc(item.title)}</strong><p>Listed price: <b>${formatPrice(item.price)}</b></p><small>Seller: ${esc(sellerName(item.sellerId))}</small></div></div><form id="offer-form" data-listing="${esc(id)}"><div class="form-grid"><div class="form-field"><label>Your offer (₹) *</label><input name="price" type="number" min="1" required placeholder="Enter your offer"></div><div class="form-field"><label>Message to seller</label><input name="message" placeholder="A short note (optional)"></div></div><div class="form-actions"><button type="button" class="button button-muted" data-action="close-modal">Cancel</button><button class="button button-primary">Send private offer ↗</button></div></form></div>`)}
async function updateOffer(offerId,action){if(liveMode){try{await CHB.updateOffer(offerId,action==='accept'?'Accepted':'Declined');await refreshLiveData();toast(action==='accept'?'Offer accepted.':'Offer declined.');}catch(err){toast(err.message)}return}let found=null;for(const item of listings){const o=(item.offers||[]).find(x=>x.id===offerId);if(o){found={item,o};break}}if(!found)return;found.o.status=action==='accept'?'Accepted':'Declined';persist();toast(`Offer ${found.o.status.toLowerCase()}.`);renderDashboard()}
async function submitListing(form){const fd=new FormData(form);const externalRaw=String(fd.get('external_url')||'').trim();const externalUrl=chbCleanHttpUrl(externalRaw);if(externalRaw&&!externalUrl){toast('Please enter a valid external link starting with http:// or https://.');return}const price=Math.max(0,Number(fd.get('price')||0));const subjectValue=fd.get('subject')==='__other__'?String(fd.get('other_subject')||'').trim():String(fd.get('subject')||'').trim();const collegeValue=fd.get('college')==='__other__'?String(fd.get('other_college')||'').trim():String(fd.get('college')||'').trim();if(!subjectValue||!collegeValue){toast('Please enter the custom subject or university name.');return}if(liveMode){if(!currentAuthUser){openLoginModal();return}const isBook=fd.get('kind')==='Books',category=fd.get('category')||(isBook?'Textbooks':'Handwritten Notes');const payload={title:String(fd.get('title')).trim(),author:String(fd.get('author')||'Student-made resource'),subject:subjectValue,college:collegeValue,branch:fd.get('branch'),year:Number(fd.get('year')||currentUser.year),semester:Number(fd.get('semester')||currentUser.semester),category,type:isBook?'Books':category==='PYQs'?'PYQs':category==='Lab Manuals'?'Lab Manuals':category==='Study Guides'?'Study Guides':category==='Handwritten Notes'?'Handwritten Notes':'Digital Notes',price,condition:fd.get('condition'),description:String(fd.get('description')||'').trim(),externalUrl,negotiation:fd.get('negotiation')==='yes',filePath:form.dataset.editId?(listings.find(x=>x.id===form.dataset.editId)?.filePath||null):null};const file=form.querySelector('[name="cover"]')?.files?.[0]||null;try{await CHB.createListing(currentUser.id,payload,file,form.dataset.editId||null);await refreshLiveData();closeModal();showView('home');toast('Your real listing is now published to the student community.');}catch(err){toast(err.message||'Listing could not be published.');}return}const isBook=fd.get('kind')==='Books';const category=fd.get('category')||(isBook?'Textbooks':'Handwritten Notes');const item={id:'listing-'+Date.now(),title:String(fd.get('title')).trim(),author:String(fd.get('author')||'Student-made resource'),type:isBook?'Books':category==='PYQs'?'PYQs':category==='Lab Manuals'?'Lab Manuals':category==='Study Guides'?'Study Guides':'Digital Notes',category,college:collegeValue,branch:fd.get('branch'),year:Number(fd.get('year')||currentUser.year),semester:Number(fd.get('semester')||currentUser.semester),price,free:price===0,sellerId:currentUser.id,negotiation:fd.get('negotiation')==='yes',showContact:fd.get('showContact')==='yes'&&currentUser.phoneVerified,condition:fd.get('condition'),subject:subjectValue,description:String(fd.get('description')).trim(),externalUrl,availability:'Available',createdAt:Date.now(),theme:coverThemes[Math.floor(Math.random()*coverThemes.length)],comments:[],offers:[],demo:false,fileName:form.querySelector('[name="cover"]')?.files?.[0]?.name||''};if(form.dataset.editId){const existing=listings.find(x=>x.id===form.dataset.editId);if(existing){Object.assign(existing,item,{id:existing.id,createdAt:existing.createdAt,availability:existing.availability});}}else{listings.unshift(item);}persist();closeModal();quickFilter='all';activeCategory='';activeQuery='';$('#search-input').value='';$$('.filter-tab').forEach(x=>x.classList.toggle('active',x.dataset.quickFilter==='all'));showView('home');renderGrid();toast('Your resource is live in the Campus Help marketplace!')}
async function submitRequest(form){const fd=new FormData(form);if(liveMode){if(!currentAuthUser){openLoginModal();return}try{await CHB.createRequest(currentUser.id,{title:String(fd.get('title')).trim(),subject:fd.get('subject'),college:fd.get('college'),branch:fd.get('branch'),semester:Number(fd.get('semester')),budget:fd.get('budget'),details:fd.get('details')});await refreshLiveData();closeModal();showView('requests');toast('Your request is now visible to the student community.');}catch(err){toast(err.message)}return}requests.unshift({id:'req-'+Date.now(),title:String(fd.get('title')).trim(),subject:fd.get('subject'),college:fd.get('college'),branch:fd.get('branch'),semester:Number(fd.get('semester')),budget:fd.get('budget'),details:fd.get('details'),userId:currentUser.id,createdAt:Date.now()});persist();closeModal();showView('requests');toast('Your material request has been posted.')}
async function submitComment(form){const item=listings.find(x=>x.id===modalListingId);if(!item)return;const text=String(new FormData(form).get('comment')||'').trim();if(!text)return;if(liveMode){if(!currentAuthUser){openLoginModal();return}try{await CHB.addComment(item.id,text);item.comments=await CHB.loadComments(item.id);item.commentsLoaded=true;item.comments.forEach(c=>{if(c.profile)liveProfiles[c.userId]=c.profile});openListing(item.id);toast('Your question has been posted.');}catch(err){toast(err.message)}return}(item.comments||(item.comments=[])).push({id:'comment-'+Date.now(),userId:currentUser.id,text,createdAt:Date.now()});persist();openListing(item.id);toast('Your question has been posted.')}
async function submitOffer(form){const item=listings.find(x=>x.id===form.dataset.listing);if(!item)return;const fd=new FormData(form);if(liveMode){if(!currentAuthUser){openLoginModal();return}try{await CHB.addOffer(item.id,Number(fd.get('price')),String(fd.get('message')||''));await refreshLiveData();closeModal();toast('Private offer sent to the seller.');}catch(err){toast(err.message)}return}(item.offers||(item.offers=[])).push({id:'offer-'+Date.now(),userId:currentUser.id,price:Number(fd.get('price')),message:String(fd.get('message')||''),createdAt:Date.now(),status:'Pending'});persist();closeModal();toast('Private offer sent to the seller.');}
async function submitChat(form){const t=threads.find(x=>x.id===selectedThreadId);if(!t)return;const text=String(new FormData(form).get('message')||'').trim();if(!text)return;if(liveMode){try{const other=t.members.find(x=>x!==currentUser.id);await CHB.sendMessage(currentUser.id,other,t.listingId,text);threads=await CHB.loadThreads(currentUser.id);threads.forEach(x=>Object.assign(liveProfiles,x.profiles||{}));renderMessages();}catch(err){toast(err.message)}return}t.messages.push({from:currentUser.id,text,time:Date.now()});persist();renderChatPanel();}
function submitPrivacy(form){const val=new FormData(form).get('profileContact')==='yes';if(liveMode&&val){toast('Public phone display is disabled until a real phone-verification flow is configured. In-app contact remains available.');return}if(val&&!currentUser.phoneVerified){toast('Verify your phone with OTP before enabling contact visibility.');return}currentUser={...currentUser,showContact:val};demoUsers[currentUser.id].showContact=val;closeModal();toast('Privacy preference saved for this demo profile.');}
function setupEvents(){document.addEventListener('click',handleClick);$('#profile-menu-button').addEventListener('click',e=>{$('#profile-menu').classList.toggle('hidden');e.stopPropagation()});document.addEventListener('click',e=>{if(!e.target.closest('#profile-menu')&&!e.target.closest('#profile-menu-button'))$('#profile-menu').classList.add('hidden')});$$('.switch-user').forEach(b=>b.addEventListener('click',()=>{currentUser=demoUsers[b.dataset.user];writeStore(DB.users,currentUser.id);updateHeader();$('#profile-menu').classList.add('hidden');toast(`Switched to ${currentUser.name}.`);if(activeView==='dashboard')renderDashboard();if(activeView==='messages')renderMessages()}));$('#search-button').addEventListener('click',runSearch);$('#search-input').addEventListener('keydown',e=>{if(e.key==='Enter')runSearch()});$('#search-input').addEventListener('input',()=>$('#clear-search').classList.toggle('hidden',!$('#search-input').value));$('#clear-search').addEventListener('click',()=>{$('#search-input').value='';activeQuery='';$('#clear-search').classList.add('hidden');renderGrid()});$('#college-filter').addEventListener('change',()=>{toggleFilterOtherFields();populateSubjectFilter();renderGrid()});$('#semester-filter').addEventListener('change',()=>{populateSubjectFilter();renderGrid()});$('#subject-filter').addEventListener('change',()=>{toggleFilterOtherFields();renderGrid()});['other-university-filter','other-subject-filter'].forEach(id=>$('#'+id).addEventListener('input',()=>renderGrid()));$('#sort-filter').addEventListener('change',()=>renderGrid());$('#modal-root').addEventListener('change',e=>{if(e.target.id==='listing-college')syncOtherFormField('listing-college','other-college-input');if(e.target.id==='listing-subject')syncOtherFormField('listing-subject','other-subject-input')});$('#reset-filters').addEventListener('click',()=>{activeQuery='';activeCategory='';quickFilter='all';$('#search-input').value='';$('#college-filter').value='';$('#semester-filter').value='';$('#subject-filter').value='';$('#sort-filter').value='recent';$('#other-university-filter').value='';$('#other-subject-filter').value='';toggleFilterOtherFields();populateSubjectFilter();$$('.filter-tab').forEach(x=>x.classList.toggle('active',x.dataset.quickFilter==='all'));renderGrid()});$('#load-more').addEventListener('click',()=>{visibleCount+=12;renderGrid()});$('#modal-root').addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();submitAuthForm(e.target)}if(e.target.id==='profile-completion-form'){e.preventDefault();const fd=new FormData(e.target);CHB.saveProfile(currentAuthUser,{full_name:fd.get('full_name'),college:fd.get('college'),course:fd.get('course'),branch:fd.get('branch'),academic_year:fd.get('academic_year'),semester:fd.get('semester')}).then(p=>{liveProfiles[p.id]=p;currentUser=p;closeModal();refreshLiveData();toast('Student profile saved.')}).catch(err=>toast(err.message))}if(e.target.id==='listing-form'){e.preventDefault();submitListing(e.target)}if(e.target.id==='request-form'){e.preventDefault();submitRequest(e.target)}if(e.target.id==='comment-form'){e.preventDefault();submitComment(e.target)}if(e.target.id==='offer-form'){e.preventDefault();submitOffer(e.target)}});$('#other-page').addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();submitChat(e.target)}if(e.target.id==='phone-contact-form'){e.preventDefault();submitPhoneContact(e.target)}})}
function runSearch(){activeQuery=$('#search-input').value.trim();activeCategory='';quickFilter='all';$$('.filter-tab').forEach(x=>x.classList.toggle('active',x.dataset.quickFilter==='all'));renderGrid();document.querySelector('#marketplace').scrollIntoView({behavior:'smooth'});}
function boot(){liveMode=true;listings=[];requests=[];threads=[];wishlist={};currentUser={id:'guest',name:'Campus Guest',initials:'CG',college:'Browse mode',course:'',branch:'',year:1,semester:1,emailVerified:false,phoneVerified:false,collegeVerified:false,showContact:false,color:'blue'};if(window.CHB?.configured){$('#mode-badge').textContent='LIVE COMMUNITY';$('.footer-copy').textContent='© 2026 Campus Help Bridge · Live student community';}else{$('#mode-badge').textContent='BACKEND NOT CONFIGURED';$('.footer-copy').textContent='© 2026 Campus Help Bridge · No demo data is displayed';}updateHeader();populateBrowseFilters();setupEvents();renderGrid();$('#result-count').textContent=`Showing ${Math.min(12,listings.length)} of ${listings.length} resources`;}
boot();
initializeLiveMode();
